def search(arr):
    """Find the unique element in a sorted array where all others occur twice."""
    if not arr:
        raise ValueError("Array must not be empty")

    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2
        if mid % 2 == 1:
            mid -= 1

        if arr[mid] == arr[mid + 1]:
            left = mid + 2
        else:
            right = mid

    return arr[left]
